CREATE TYPE "AccountType" AS ENUM ('personal','work_school');
CREATE TYPE "WorkspaceType" AS ENUM ('personal');
CREATE TABLE "User" ("id" uuid PRIMARY KEY,"providerSubject" text NOT NULL UNIQUE,"providerTenantId" text,"accountType" "AccountType" NOT NULL,"displayName" text,"emailHint" text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"lastLoginAt" timestamptz,"disabledAt" timestamptz);
CREATE TABLE "Workspace" ("id" uuid PRIMARY KEY,"ownerUserId" uuid NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE RESTRICT,"name" text NOT NULL,"type" "WorkspaceType" NOT NULL DEFAULT 'personal',"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"archivedAt" timestamptz);
CREATE TABLE "Session" ("id" uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"workspaceId" uuid NOT NULL REFERENCES "Workspace"("id") ON DELETE RESTRICT,"csrfHash" text NOT NULL,"expiresAt" timestamptz NOT NULL,"revokedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "Session_user_expiry" ON "Session"("userId","expiresAt");
CREATE TABLE "Resource" ("id" uuid NOT NULL,"workspaceId" uuid NOT NULL REFERENCES "Workspace"("id") ON DELETE RESTRICT,"kind" text NOT NULL,"title" text NOT NULL,"parentId" uuid,"version" integer NOT NULL DEFAULT 1,"archivedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),PRIMARY KEY("workspaceId","id"),FOREIGN KEY("workspaceId","parentId") REFERENCES "Resource"("workspaceId","id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "Resource_title_per_workspace_kind" ON "Resource"("workspaceId","kind","title") WHERE "archivedAt" IS NULL;
CREATE TABLE "AuditEvent" ("id" uuid PRIMARY KEY,"workspaceId" uuid NOT NULL REFERENCES "Workspace"("id") ON DELETE RESTRICT,"actorUserId" uuid NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"action" text NOT NULL,"targetType" text,"targetId" text,"outcome" text NOT NULL,"metadata" jsonb,"createdAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "Audit_workspace_created" ON "AuditEvent"("workspaceId","createdAt");
CREATE TABLE "ImportReport" ("id" uuid PRIMARY KEY,"workspaceId" uuid NOT NULL REFERENCES "Workspace"("id") ON DELETE RESTRICT,"importHash" text NOT NULL,"status" text NOT NULL,"mapping" jsonb NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("workspaceId","importHash"));
